'use strict';
const fs = require('fs');
const path = require('path');

const contractsDir = path.resolve(__dirname, 'contracts');

// ============================================================================
// 1. Generate anlgram-migration-router-f02.fc
// ============================================================================
let routerCode = fs.readFileSync(path.join(contractsDir, 'anlgram-migration-router-dispatch-v2.fc'), 'utf8');

routerCode = routerCode.replace(
  ';; VERSIONED V2 DERIVATIVE. Source generated by compile-migration-package-v2.js.',
  ';; ISOLATED F-02 CANDIDATE: Authenticated STON.fi v2.2 Terminal Settlement & Recovery.'
);

routerCode = routerCode.replace(
  '#include "imports/settlement-protocol.fc";',
  '#include "imports/settlement-protocol.fc";\n#include "imports/stonfi-terminal-settlement.fc";'
);

// Intercept 0x414c5635 and 0x414c5005 before handle_migration_lp_v2
const routerInterceptPoint = '    if(handle_migration_lp_v2(my_balance,msg_value,in_msg_full,in_msg_body)) { return (); }';

const f02RouterIntercept = `    if (in_msg_body.slice_bits() >= 96) {
        int check_op = in_msg_body.preload_uint(32);
        if ((check_op == 0x414c5635) | (check_op == op::lp_custody_receipt)) {
            slice s_body = in_msg_body;
            int op = s_body~load_uint(32);
            int query_id = s_body~load_uint(64);
            (int flight_id, _, _, _, _, _) = load_flight();
            (
                int is_initialized, slice curve_address, slice lp_locker_address, slice dex_router_address,
                slice token_minter_address, slice pton_minter_address, int ton_liquidity, int tokens_liquidity, slice admin_address,
                slice expected_lp_wallet, slice expected_pton_wallet, int pending_ton, int pending_tokens, cell jetton_wallet_code
            ) = load_data();
            throw_unless(ERROR_UNAUTHORIZED_SENDER, equal_slices(sender_address, v2_vault()));
            throw_unless(ERROR_INVALID_STATE, query_id == flight_id);

            slice pool = my_address();
            slice wallet = my_address();
            int amount = 0;
            int locked_lp = 0;
            if (op == op::lp_custody_receipt) {
                pool = s_body~load_msg_addr();
                wallet = s_body~load_msg_addr();
                amount = s_body~load_coins();
                locked_lp = amount;
                s_body~load_uint(1);
                s_body.end_parse();
            } else {
                s_body~load_uint(64); ;; lt
                amount = s_body~load_coins();
                locked_lp = s_body~load_coins();
                s_body~load_coins(); ;; free
                int pending = s_body~load_coins();
                s_body~load_uint(64); ;; unlock
                throw_unless(409, pending == 0);
                slice endpoints = s_body~load_ref().begin_parse();
                pool = endpoints~load_msg_addr();
                wallet = endpoints~load_msg_addr();
                endpoints.end_parse();
                s_body.end_parse();
            }
            throw_unless(ERROR_INVALID_ADDRESS, (pool.preload_uint(2) == 2) & equal_slices(wallet, expected_lp_wallet));
            throw_unless(ERROR_INVALID_STATE, amount > 0);

            (int stage, int opened, int epoch, int ot, int oj, int rt, int rj, int cumulative) = load_reconciliation();
            cell lp = begin_cell().store_slice(pool).store_slice(wallet).store_coins(amount).end_cell();

            ;; Complete authenticated F-02 terminal settlement:
            pending_ton = 0;
            pending_tokens = 0;
            is_initialized = 0;
            save_data(0, curve_address, lp_locker_address, dex_router_address,
                token_minter_address, pton_minter_address, 0, 0, admin_address,
                expected_lp_wallet, expected_pton_wallet, 0, 0, jetton_wallet_code);
            save_reconciliation_with_receipts(8, opened, epoch, ot, oj, rt, rj, cumulative, native_receipts(), lp);

            ;; Emit authenticated terminal settlement proof to Bonding Curve in reference cell to avoid cell overflow:
            cell proof_payload = begin_cell()
                .store_uint(op::terminal_settlement_proof, 32)
                .store_uint(query_id, 64)
                .store_slice(pool)
                .store_slice(wallet)
                .store_coins(amount)
                .store_coins(locked_lp)
                .end_cell();
            var proof_msg = begin_cell()
                .store_uint(0x18, 6)
                .store_slice(curve_address)
                .store_coins(30000000)
                .store_uint(1, 1 + 4 + 4 + 64 + 32 + 1 + 1)
                .store_ref(proof_payload);
            send_raw_message(proof_msg.end_cell(), 1);
            return ();
        }
    }
    if (in_msg_body.slice_bits() >= 32) {
        if (in_msg_body.preload_uint(32) == op::stonfi_refund_me) {
            in_msg_body~load_uint(32);
            int query_id = in_msg_body~load_uint(64);
            (
                _, slice curve_address, _, _,
                _, _, _, _, slice admin_address,
                _, _, _, _, _
            ) = load_data();
            throw_unless(ERROR_UNAUTHORIZED_SENDER, equal_slices(sender_address, admin_address) | equal_slices(sender_address, curve_address));
            slice lp_account = in_msg_body~load_msg_addr();
            in_msg_body.end_parse();
            throw_unless(ERROR_INVALID_ADDRESS, lp_account.preload_uint(2) == 2);
            throw_unless(ERROR_INSUFFICIENT_GAS, msg_value >= 150000000);
            cell refund_msg = begin_cell()
                .store_uint(op::stonfi_refund_me, 32)
                .store_uint(query_id, 64)
                .store_uint(0, 2)
                .end_cell();
            send_raw_message(begin_cell()
                .store_uint(0x18, 6)
                .store_slice(lp_account)
                .store_coins(100000000)
                .store_uint(1, 107)
                .store_ref(refund_msg)
                .end_cell(), 1);
            return ();
        }
    }
    if(handle_migration_lp_v2(my_balance,msg_value,in_msg_full,in_msg_body)) { return (); }`;

routerCode = routerCode.replace(routerInterceptPoint, f02RouterIntercept);
fs.writeFileSync(path.join(contractsDir, 'anlgram-migration-router-f02.fc'), routerCode, 'utf8');
console.log('Created minter-contract/contracts/anlgram-migration-router-f02.fc');

// ============================================================================
// 2. Generate anlgram-bonding-curve-f02.fc
// ============================================================================
let curveCode = fs.readFileSync(path.join(contractsDir, 'anlgram-bonding-curve-dispatch-v2.fc'), 'utf8');

curveCode = curveCode.replace(
  '#include "imports/dispatch-sell-custody.fc";',
  '#include "imports/dispatch-sell-custody.fc";\n#include "imports/stonfi-terminal-settlement.fc";'
);

const curveInterceptPoint = '    curve_v2_validate_request(op,query_id,sender_address);';

const f02CurveIntercept = `    if (op == op::terminal_settlement_proof) {
        throw_unless(ERROR_UNAUTHORIZED, equal_slices(sender_address, migration_router_address));
        throw_unless(ERROR_INVALID_STATE, state == STATE_MIGRATION_IN_PROGRESS);
        slice proof_slice = in_msg_body;
        if (in_msg_body.slice_refs()) {
            proof_slice = in_msg_body~load_ref().begin_parse();
            proof_slice~load_uint(32); ;; op
            proof_slice~load_uint(64); ;; query_id
        }
        slice pool = proof_slice~load_msg_addr();
        slice lp_wallet = proof_slice~load_msg_addr();
        int lp_amount = proof_slice~load_coins();
        int locked_amount = proof_slice~load_coins();
        proof_slice.end_parse();
        throw_unless(ERROR_ZERO_INPUT, lp_amount > 0);
        throw_unless(ERROR_ZERO_INPUT, locked_amount > 0);

        state = STATE_GRADUATED;
        real_ton_reserve = 0;
        dex_tokens_escrow = 0;

        save_data(
            state, admin_address, creator_address, treasury_address,
            jetton_master_address, curve_jetton_wallet, dex_router_address, lp_locker_address, migration_router_address,
            real_ton_reserve, real_token_reserve, accrued_protocol_fees, pending_refunds_tokens,
            virtual_ton_reserve, virtual_token_reserve, graduation_threshold_ton, dex_tokens_escrow,
            pending_refunds_dict, jetton_wallet_code
        );
        return ();
    }
    curve_v2_validate_request(op,query_id,sender_address);`;

curveCode = curveCode.replace(curveInterceptPoint, f02CurveIntercept);
fs.writeFileSync(path.join(contractsDir, 'anlgram-bonding-curve-f02.fc'), curveCode, 'utf8');
console.log('Created minter-contract/contracts/anlgram-bonding-curve-f02.fc');
